package vn.gomviet.service;
import com.fasterxml.jackson.databind.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import org.springframework.web.client.RestClient;import vn.gomviet.dto.ChatDtos;import vn.gomviet.exception.ApiException;import vn.gomviet.repository.ProductRepository;import java.util.*;
@Service public class GeminiChatService{private final ProductRepository products;private final RestClient client;private final ObjectMapper json;private final String model;public GeminiChatService(ProductRepository products,ObjectMapper json,@Value("${app.gemini.api-key:}")String key,@Value("${app.gemini.model}")String model){this.products=products;this.json=json;this.model=model;this.client=RestClient.builder().baseUrl("https://generativelanguage.googleapis.com").defaultHeader("x-goog-api-key",key).build();}public ChatDtos.Response chat(ChatDtos.Request request){var catalog=products.findAllByActiveTrue().stream().map(p->Map.of("id",p.getId(),"name",p.getName(),"price",p.getPrice(),"stock",p.getStockQuantity())).toList();var prompt="Bạn là tư vấn viên Gốm Việt. Chỉ dùng catalog, trả JSON gồm answer và recommendations[{productId,reason}]. Catalog: "+catalog+" Lịch sử: "+request.messages();try{var body=Map.of("contents",List.of(Map.of("parts",List.of(Map.of("text",prompt)))),"generationConfig",Map.of("responseMimeType","application/json"));var root=client.post().uri("/v1beta/models/{model}:generateContent",model).body(body).retrieve().body(JsonNode.class);var text=root.at("/candidates/0/content/parts/0/text").asText();var answer=json.readValue(text,ChatDtos.Response.class);var valid=answer.recommendations()==null?List.<ChatDtos.Recommendation>of():answer.recommendations().stream().filter(r->catalog.stream().anyMatch(p->Objects.equals(p.get("id"),r.productId())&&((int)p.get("stock"))>0)).toList();return new ChatDtos.Response(answer.answer(),valid);}catch(Exception e){throw new ApiException(HttpStatus.BAD_GATEWAY,"Không thể kết nối trợ lý Gemini");}}}
